-- Table: pages (4 rows)
INSERT OR REPLACE INTO `pages` (`id`, `slug`, `title`, `body`, `published`, `created_at`, `updated_at`) VALUES (1, 'about', '{"en":"About the Holy Sanctum","bn":""}', '{"en":"Golpahar Mohashoshan Kali Mandir is a sacred refuge of worship, prayer, peace, and spiritual awakening in Chittagong, Bangladesh. For generations, devotees gather here for divine darshan of Bhavatarini Maa Kali, partake in evening aarti lamps, and partake in daily community Annadanam prasad.","bn":""}', 1, 1794723894859, 1794723894859);
INSERT OR REPLACE INTO `pages` (`id`, `slug`, `title`, `body`, `published`, `created_at`, `updated_at`) VALUES (2, 'plan-a-visit', '{"en":"Plan Your Holy Visit","bn":""}', '{"en":"Temple gates open daily from 5:00 AM to 1:00 PM, and re-open from 4:30 PM to 9:30 PM. Devotees are requested to dress respectfully, remove footwear before entering the parikrama hall, and maintain quiet sanctity within the garbhagriha.","bn":""}', 1, 1794723894859, 1794723894859);
INSERT OR REPLACE INTO `pages` (`id`, `slug`, `title`, `body`, `published`, `created_at`, `updated_at`) VALUES (3, 'history', '{"en":"Sacred Origins & History","bn":""}', '{"en":"Rooted in the eternal spiritual tradition of Chattogram, Golpahar is celebrated as an ancient seat of tantric sadhana and devotion to Mahashoshan Kali. The temple has stood through centuries as a beacon of resilience, faith, and unconditional divine sanctuary.","bn":""}', 1, 1794723894859, 1794723894859);
INSERT OR REPLACE INTO `pages` (`id`, `slug`, `title`, `body`, `published`, `created_at`, `updated_at`) VALUES (4, 'seva', '{"en":"Partake in Devotee Seva","bn":""}', '{"en":"Seva is at the heart of our mandir. From early morning flower garlands and Vedic Chandi chanting to mid-day Annadanam cooking and holy prasad distribution, all devotees are welcome to offer their heartfelt service.","bn":""}', 1, 1794723894859, 1794723894859);

